//! Byte-for-byte parity with the verified TypeScript modules, for Risk Guard v3.1.
//!
//! `tests/fixtures/hl_vectors_v31.json` is generated by `scripts/hl-vectors-v31.ts` from
//! `src/lib/hyperliquid/{exchangeSigning,fixedPoint,v31Hedge}.ts` (which match the official SDK vectors).
//! `tests/hlParity.test.ts` regenerates it in CI and fails if it is stale.

use near_sdk::serde_json::{self, Value};
use zerodelta_risk_guard_v31::hl::{self, OrderWire, Tif};

const VECTORS: &str = include_str!("fixtures/hl_vectors_v31.json");

fn v() -> Value {
    serde_json::from_str(VECTORS).unwrap()
}

fn u(x: &Value) -> u64 {
    match x {
        Value::String(s) => s.parse().unwrap(),
        other => other.as_u64().unwrap(),
    }
}

fn tif(s: &str) -> Tif {
    match s {
        "Alo" => Tif::Alo,
        "Ioc" => Tif::Ioc,
        "Gtc" => Tif::Gtc,
        _ => panic!("tif {}", s),
    }
}

#[test]
fn float_to_wire_matches_ts() {
    let v = v();
    let cases = v["wire"].as_array().unwrap();
    assert!(cases.len() >= 30);
    for c in cases {
        assert_eq!(hl::wire_e8(u(&c["e8"])), c["wire"].as_str().unwrap(), "x = {}", c["x"]);
    }
}

#[test]
fn every_order_action_with_and_without_expires_after_matches_ts_byte_for_byte() {
    let v = v();
    let cases = v["orders"].as_array().unwrap();
    assert_eq!(cases.len(), 64);
    let (mut with_expiry, mut without) = (0, 0);
    for c in cases {
        let id = &c["id"];
        let orders: Vec<OrderWire> = c["orders"]
            .as_array()
            .unwrap()
            .iter()
            .map(|o| OrderWire {
                asset: u(&o["asset"]) as u32,
                is_buy: o["isBuy"].as_bool().unwrap(),
                px_e8: u(&o["pxE8"]),
                sz_e8: u(&o["szE8"]),
                reduce_only: o["reduceOnly"].as_bool().unwrap(),
                tif: tif(o["tif"].as_str().unwrap()),
            })
            .collect();
        let nonce = u(&c["nonce"]);
        let expiry = if c["expiresAfter"].is_null() { None } else { Some(u(&c["expiresAfter"])) };
        if expiry.is_some() {
            with_expiry += 1;
        } else {
            without += 1;
        }
        let packed = hl::to_msgpack(&hl::order_action(&orders));
        assert_eq!(hl::hex(&packed), c["msgpackHex"].as_str().unwrap(), "case {} msgpack", id);
        let conn = hl::connection_id(&packed, nonce, expiry);
        assert_eq!(hl::hex(&conn), c["connectionIdHex"].as_str().unwrap(), "case {} connectionId", id);
        let digest = hl::l1_digest(&conn, c["isMainnet"].as_bool().unwrap());
        assert_eq!(hl::hex(&digest), c["digestHex"].as_str().unwrap(), "case {} digest", id);
        assert_eq!(digest, hl::order_digest(&orders, nonce, expiry, c["isMainnet"].as_bool().unwrap()));
    }
    assert!(with_expiry >= 40 && without >= 10, "{} / {}", with_expiry, without);
}

#[test]
fn exact_sizing_matches_ts() {
    let v = v();
    let cases = v["sizing"].as_array().unwrap();
    assert!(cases.len() >= 400);
    for c in cases {
        let szd = u(&c["szDecimals"]) as u8;
        let lots = hl::size_lots(u(&c["cents"]), u(&c["pxE8"]), szd).unwrap();
        assert_eq!(lots, u(&c["lots"]), "{}", c);
        assert_eq!(hl::lots_to_e8(lots, szd).unwrap(), u(&c["sizeE8"]), "{}", c);
    }
}

#[test]
fn price_rules_match_ts() {
    let v = v();
    let cases = v["priceRules"].as_array().unwrap();
    assert!(cases.len() >= 100);
    let mut rejected = 0;
    for c in cases {
        let got = hl::check_perp_price(u(&c["pxE8"]), u(&c["szDecimals"]) as u8).err();
        let want = c["violation"].as_str().map(|s| s.to_string());
        if want.is_some() {
            rejected += 1;
        }
        assert_eq!(got, want, "{}", c);
    }
    assert!(rejected > 20 && rejected < cases.len() - 20, "both valid and invalid prices are covered");
}

mod contract_level {
    use super::*;
    use near_sdk::test_utils::VMContextBuilder;
    use near_sdk::{testing_env, AccountId, NearToken};
    use zerodelta_risk_guard_v31::{HedgeRequest, Market, OrderParams, Policy, RiskGuardV31};

    fn policy(p: &Value) -> Policy {
        Policy {
            max_delta_bps: 200,
            max_leverage_x100: 300,
            max_slippage_bps: 25,
            price_band_bps: u(&p["price_band_bps"]) as u32,
            notional_band_bps: u(&p["notional_band_bps"]) as u32,
            max_nonce_age_ms: u(&p["max_nonce_age_ms"]),
            max_nonce_future_ms: u(&p["max_nonce_future_ms"]),
            max_expiry_ms: u(&p["max_expiry_ms"]),
            window_ms: 86_400_000,
            max_orders_per_window: 6,
        }
    }

    fn markets(p: &Value, net: &str) -> Vec<Market> {
        p["markets"][net]
            .as_array()
            .unwrap()
            .iter()
            .map(|m| Market {
                symbol: m["symbol"].as_str().unwrap().into(),
                asset: u(&m["asset"]) as u32,
                sz_decimals: u(&m["sz_decimals"]) as u8,
                max_order_size_e8: u(&m["max_order_size_e8"]),
                window_size_cap_e8: u(&m["window_size_cap_e8"]),
            })
            .collect()
    }

    #[test]
    fn contract_builds_exactly_what_the_ts_mirror_predicts() {
        let v = v();
        let p = &v["v31Parity"];
        let contract_id: AccountId = p["contractId"].as_str().unwrap().parse().unwrap();
        let block_ms = u(&p["blockTimeMs"]);
        let mut b = VMContextBuilder::new();
        b.current_account_id(contract_id.clone()).predecessor_account_id(contract_id).block_timestamp(block_ms * 1_000_000).attached_deposit(NearToken::from_yoctonear(0));
        testing_env!(b.build());
        let tn = RiskGuardV31::new("solver.testnet".parse().unwrap(), policy(&p["policy"]), "testnet".into(), markets(p, "testnet"), "2026-11-11T13:58:03Z".into(), None, None, None);
        let mn = RiskGuardV31::new("solver.testnet".parse().unwrap(), policy(&p["policy"]), "mainnet".into(), markets(p, "mainnet"), "2026-11-09".into(), None, None, None);

        let cases = v["hedges"].as_array().unwrap();
        assert!(cases.len() >= 120);
        let (mut approved, mut inflation_refused, mut cap_refused, mut min_refused) = (0, 0, 0, 0);
        for c in cases {
            let o = &c["order"];
            let req = HedgeRequest {
                run_id: "parity".into(),
                order: OrderParams {
                    asset_symbol: o["asset_symbol"].as_str().unwrap().into(),
                    treasury_usd_cents: u(&o["treasury_usd_cents"]),
                    spot_long_usd_cents: u(&o["spot_long_usd_cents"]),
                    perp_short_usd_cents: u(&o["perp_short_usd_cents"]),
                    perp_long_usd_cents: u(&o["perp_long_usd_cents"]),
                    collateral_usd_cents: u(&o["collateral_usd_cents"]),
                    quoted_slippage_bps: u(&o["quoted_slippage_bps"]) as u32,
                    nonce: u(&o["nonce"]),
                },
                limit_px_e8: u(&c["limitPxE8"]),
                reference_px_e8: u(&c["referencePxE8"]),
                expires_after_ms: u(&c["expiresAfterMs"]),
                expected_digest_hex: None,
                plan_hash: "a".repeat(64),
                intent_payload_hash: "b".repeat(64),
                attestation_report_hash: "c".repeat(64),
                decision_hash: "d".repeat(64),
            };
            let g = if c["hlNetwork"] == "mainnet" { &mn } else { &tn };
            let e = g.preview_executable_hedge(req);
            let why = format!("{} / {}", c["why"], c["hlNetwork"]);
            let want: Vec<String> = c["violations"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().to_string()).collect();
            assert_eq!(e.violations, want, "{}", why);
            assert_eq!(e.size_e8, u(&c["sizeE8"]), "{}", why);
            assert_eq!(e.price_deviation_bps, u(&c["priceDeviationBps"]), "{}", why);
            assert_eq!(e.notional_drift_bps, u(&c["notionalDriftBps"]), "{}", why);
            assert_eq!(e.action_json, c["actionJson"].as_str().unwrap(), "{}", why);
            assert_eq!(e.connection_id_hex, c["connectionIdHex"].as_str().unwrap(), "{}", why);
            assert_eq!(e.digest_hex, c["digestHex"].as_str().unwrap(), "{}", why);
            assert_eq!(e.commitment_hex, c["commitmentHex"].as_str().unwrap(), "{}", why);
            assert_eq!(e.expires_after_ms, u(&c["expiresAfterMs"]), "{}", why);
            if e.approved {
                approved += 1;
            }
            if c["why"].as_str().unwrap().starts_with("inflation") && e.violations.iter().any(|x| x.starts_with("ORDER_SIZE_CAP")) {
                inflation_refused += 1;
            }
            if e.violations.iter().any(|x| x.starts_with("ORDER_SIZE_CAP")) {
                cap_refused += 1;
            }
            if e.violations.iter().any(|x| x.starts_with("ORDER_VALUE_BELOW_MIN")) {
                min_refused += 1;
            }
        }
        assert!(approved >= 40 && approved < cases.len(), "approved {} of {}", approved, cases.len());
        assert!(inflation_refused >= 6, "audit-attack cases refused by the coin cap: {}", inflation_refused);
        assert!(cap_refused >= inflation_refused && min_refused >= 4, "cap {} min {}", cap_refused, min_refused);
    }
}
